
// src/lib/firebase/admin.ts
import * as admin from 'firebase-admin';
import * as dotenv from 'dotenv';

// Load environment variables from .env.local
dotenv.config();

const initializeFirebaseAdmin = () => {
  // Check if the app is already initialized to prevent errors.
  if (admin.apps.length > 0) {
    return admin.app();
  }

  // The SDK will automatically use the GOOGLE_APPLICATION_CREDENTIALS environment
  // variable to find the service account file.
  try {
    admin.initializeApp();
  } catch (error: any) {
    console.error('Firebase admin initialization error', error.stack);
    // Throw a more specific error to help with debugging.
    throw new Error(`Firebase admin initialization failed: ${error.message}`);
  }

  return admin.app();
};

// Helper function to get the auth service
function getFirebaseAuth() {
  initializeFirebaseAdmin();
  return admin.auth();
}

// Helper function to get the firestore service
function getFirestoreDB() {
  initializeFirebaseAdmin();
  return admin.firestore();
}

// Export the initialized services
export const auth = getFirebaseAuth();
export const db = getFirestoreDB();
